-- Encryption metadata, disappearing-message policy, call signaling, and embed tokens
ALTER TABLE "messages" ADD COLUMN "encryption_mode" TEXT NOT NULL DEFAULT 'server';
ALTER TABLE "messages" ADD COLUMN "disappearing_after_seconds" INTEGER;
ALTER TABLE "messages" ADD COLUMN "expires_at" TIMESTAMP(3);
CREATE INDEX "messages_expires_at_idx" ON "messages"("expires_at");
CREATE TABLE "call_sessions" ("id" TEXT NOT NULL, "company_id" TEXT NOT NULL, "room_id" TEXT NOT NULL, "initiated_by" TEXT NOT NULL, "kind" TEXT NOT NULL, "status" TEXT NOT NULL DEFAULT 'ringing', "metadata" JSONB, "started_at" TIMESTAMP(3), "ended_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMP(3) NOT NULL, CONSTRAINT "call_sessions_pkey" PRIMARY KEY ("id"), CONSTRAINT "call_sessions_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "companies"("id") ON DELETE CASCADE, CONSTRAINT "call_sessions_room_id_fkey" FOREIGN KEY ("room_id") REFERENCES "chat_rooms"("id") ON DELETE CASCADE, CONSTRAINT "call_sessions_initiated_by_fkey" FOREIGN KEY ("initiated_by") REFERENCES "accounts"("id"));
CREATE INDEX "call_sessions_company_id_created_at_idx" ON "call_sessions"("company_id", "created_at");
CREATE TABLE "call_participants" ("call_id" TEXT NOT NULL, "account_id" TEXT NOT NULL, "joined_at" TIMESTAMP(3), "left_at" TIMESTAMP(3), CONSTRAINT "call_participants_pkey" PRIMARY KEY ("call_id", "account_id"), CONSTRAINT "call_participants_call_id_fkey" FOREIGN KEY ("call_id") REFERENCES "call_sessions"("id") ON DELETE CASCADE, CONSTRAINT "call_participants_account_id_fkey" FOREIGN KEY ("account_id") REFERENCES "accounts"("id") ON DELETE CASCADE);
CREATE TABLE "call_signal_events" ("id" TEXT NOT NULL, "call_id" TEXT NOT NULL, "sender_id" TEXT NOT NULL, "event_type" TEXT NOT NULL, "payload" JSONB NOT NULL, "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "call_signal_events_pkey" PRIMARY KEY ("id"), CONSTRAINT "call_signal_events_call_id_fkey" FOREIGN KEY ("call_id") REFERENCES "call_sessions"("id") ON DELETE CASCADE, CONSTRAINT "call_signal_events_sender_id_fkey" FOREIGN KEY ("sender_id") REFERENCES "accounts"("id") ON DELETE CASCADE);
CREATE INDEX "call_signal_events_call_id_created_at_idx" ON "call_signal_events"("call_id", "created_at");
CREATE TABLE "embed_tokens" ("id" TEXT NOT NULL, "company_id" TEXT NOT NULL, "integration_id" TEXT, "token_hash" TEXT NOT NULL, "scopes" TEXT[] NOT NULL, "expires_at" TIMESTAMP(3) NOT NULL, "consumed_at" TIMESTAMP(3), "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "embed_tokens_pkey" PRIMARY KEY ("id"), CONSTRAINT "embed_tokens_token_hash_key" UNIQUE ("token_hash"), CONSTRAINT "embed_tokens_company_id_fkey" FOREIGN KEY ("company_id") REFERENCES "companies"("id") ON DELETE CASCADE, CONSTRAINT "embed_tokens_integration_id_fkey" FOREIGN KEY ("integration_id") REFERENCES "third_party_integrations"("id") ON DELETE CASCADE);
CREATE INDEX "embed_tokens_company_id_expires_at_idx" ON "embed_tokens"("company_id", "expires_at");
